metrics.workdir_dsl:
workspace "Parcel Tracker" "A parcel delivery tracking platform." {
    model {
        customer = person "Customer" "Uses the platform to look up the status of their parcels."

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company." {
            webPortal = container "Web Portal" "Where customers look up their shipments." "Web application" {
                pricingWeb = component "Pricing Rules Library" "Computes delivery prices from weight and zone." "Shared library"
            }
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers." "Service" {
                pricingDispatch = component "Pricing Rules Library" "Computes delivery prices from weight and zone." "Shared library"
            }
            database = container "Database" "Stores shipments and dispatch records." "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "Delivers customer notification emails. Operated by a different organization." "External"

        customer -> webPortal "looks up the status of their parcels"
        webPortal -> database "reads shipment records from"
        dispatchService -> database "stores dispatch records in"
        dispatchService -> emailProvider "sends customer notification emails through"
    }
}
